package com.prep2place.ratelimit;

import java.time.Clock;
import java.time.Duration;
import java.util.HashMap;
import java.util.Map;

public class RateLimiter {
    private final int maxRequests;
    private final long windowMillis;
    private final Clock clock;
    private final Map<String, long[]> state = new HashMap<>(); // clientId -> {windowStartMillis, count}

    public RateLimiter(int maxRequests, Duration window, Clock clock) {
        if (maxRequests <= 0) throw new IllegalArgumentException("maxRequests must be positive");
        if (window == null || window.isZero() || window.isNegative()) throw new IllegalArgumentException("window must be positive");
        if (clock == null) throw new IllegalArgumentException("clock is required");
        this.maxRequests = maxRequests;
        this.windowMillis = window.toMillis();
        this.clock = clock;
    }

    public synchronized boolean tryAcquire(String clientId) {
        check(clientId);
        long now = clock.millis();
        long[] s = state.get(clientId);
        if (s == null || now - s[0] >= windowMillis) {
            s = new long[]{now, 0};
            state.put(clientId, s);
        }
        if (s[1] >= maxRequests) return false;
        s[1]++;
        return true;
    }

    public synchronized int remaining(String clientId) {
        check(clientId);
        long[] s = state.get(clientId);
        if (s == null || clock.millis() - s[0] >= windowMillis) return maxRequests;
        return (int) (maxRequests - s[1]);
    }

    private static void check(String clientId) {
        if (clientId == null || clientId.isBlank()) throw new IllegalArgumentException("clientId is required");
    }
}

