package com.prep2place.ratelimit;

import org.junit.jupiter.api.Test;

import java.time.*;

import static org.junit.jupiter.api.Assertions.*;

class RateLimiterPublicTest {
    static class TestClock extends Clock {
        private Instant now = Instant.parse("2025-01-01T00:00:00Z");
        void advance(Duration d) { now = now.plus(d); }
        @Override public ZoneId getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(ZoneId zone) { return this; }
        @Override public Instant instant() { return now; }
    }

    @Test
    void r1_allowsUpToTheLimitThenRejects() {
        RateLimiter rl = new RateLimiter(3, Duration.ofSeconds(10), new TestClock());
        assertTrue(rl.tryAcquire("alice"));
        assertTrue(rl.tryAcquire("alice"));
        assertTrue(rl.tryAcquire("alice"));
        assertFalse(rl.tryAcquire("alice"));
    }

    @Test
    void r2_clientsAreTrackedIndependently() {
        RateLimiter rl = new RateLimiter(1, Duration.ofSeconds(10), new TestClock());
        assertTrue(rl.tryAcquire("alice"));
        assertFalse(rl.tryAcquire("alice"));
        assertTrue(rl.tryAcquire("bob"));
    }

    @Test
    void r3_windowResetsOnceItHasElapsed() {
        TestClock clock = new TestClock();
        RateLimiter rl = new RateLimiter(2, Duration.ofSeconds(10), clock);
        assertTrue(rl.tryAcquire("alice"));
        assertTrue(rl.tryAcquire("alice"));
        assertFalse(rl.tryAcquire("alice"));
        clock.advance(Duration.ofSeconds(11));
        assertTrue(rl.tryAcquire("alice"));
    }

    @Test
    void r4_remainingCountsDown() {
        RateLimiter rl = new RateLimiter(3, Duration.ofSeconds(10), new TestClock());
        assertEquals(3, rl.remaining("alice"));
        rl.tryAcquire("alice");
        assertEquals(2, rl.remaining("alice"));
    }
}

