package com.prep2place.ratelimit;

import org.junit.jupiter.api.Test;

import java.time.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.*;

class RateLimiterHiddenTest {
    static class TestClock extends Clock {
        private Instant now = Instant.parse("2025-01-01T00:00:00Z");
        void advance(Duration d) { now = now.plus(d); }
        @Override public ZoneId getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(ZoneId zone) { return this; }
        @Override public Instant instant() { return now; }
    }

    @Test
    void r1_limitOfOneAllowsExactlyOne() {
        RateLimiter rl = new RateLimiter(1, Duration.ofMinutes(1), new TestClock());
        assertTrue(rl.tryAcquire("c"));
        for (int i = 0; i < 5; i++) assertFalse(rl.tryAcquire("c"));
    }

    @Test
    void r2_manyClientsDoNotInterfere() {
        RateLimiter rl = new RateLimiter(2, Duration.ofMinutes(1), new TestClock());
        for (int i = 0; i < 50; i++) {
            assertTrue(rl.tryAcquire("client-" + i));
            assertTrue(rl.tryAcquire("client-" + i));
            assertFalse(rl.tryAcquire("client-" + i));
        }
    }

    @Test
    void r3_resetHappensExactlyAtTheWindowBoundary() {
        TestClock clock = new TestClock();
        RateLimiter rl = new RateLimiter(1, Duration.ofSeconds(10), clock);
        assertTrue(rl.tryAcquire("c"));
        clock.advance(Duration.ofMillis(9_999));
        assertFalse(rl.tryAcquire("c"));
        clock.advance(Duration.ofMillis(1));
        assertTrue(rl.tryAcquire("c"));
    }

    @Test
    void r3_rejectedRequestsDoNotExtendTheWindow() {
        TestClock clock = new TestClock();
        RateLimiter rl = new RateLimiter(1, Duration.ofSeconds(10), clock);
        assertTrue(rl.tryAcquire("c"));
        clock.advance(Duration.ofSeconds(6));
        assertFalse(rl.tryAcquire("c"));
        clock.advance(Duration.ofSeconds(4));
        assertTrue(rl.tryAcquire("c"));
    }

    @Test
    void r4_remainingIsFullForUnknownAndExpiredClientsAndNeverConsumes() {
        TestClock clock = new TestClock();
        RateLimiter rl = new RateLimiter(2, Duration.ofSeconds(5), clock);
        assertEquals(2, rl.remaining("nobody"));
        assertEquals(2, rl.remaining("nobody"));
        assertTrue(rl.tryAcquire("c"));
        assertTrue(rl.tryAcquire("c"));
        assertEquals(0, rl.remaining("c"));
        clock.advance(Duration.ofSeconds(5));
        assertEquals(2, rl.remaining("c"));
        assertTrue(rl.tryAcquire("c"));
    }

    @Test
    void r5_invalidArgumentsAreRejected() {
        Clock c = new TestClock();
        assertThrows(IllegalArgumentException.class, () -> new RateLimiter(0, Duration.ofSeconds(1), c));
        assertThrows(IllegalArgumentException.class, () -> new RateLimiter(-1, Duration.ofSeconds(1), c));
        assertThrows(IllegalArgumentException.class, () -> new RateLimiter(1, null, c));
        assertThrows(IllegalArgumentException.class, () -> new RateLimiter(1, Duration.ZERO, c));
        assertThrows(IllegalArgumentException.class, () -> new RateLimiter(1, Duration.ofSeconds(-1), c));
        assertThrows(IllegalArgumentException.class, () -> new RateLimiter(1, Duration.ofSeconds(1), null));
        RateLimiter rl = new RateLimiter(1, Duration.ofSeconds(1), c);
        assertThrows(IllegalArgumentException.class, () -> rl.tryAcquire(null));
        assertThrows(IllegalArgumentException.class, () -> rl.tryAcquire("  "));
        assertThrows(IllegalArgumentException.class, () -> rl.remaining(null));
    }

    @Test
    void r6_neverLetsMoreThanTheLimitThroughUnderContention() throws Exception {
        RateLimiter rl = new RateLimiter(50, Duration.ofMinutes(1), new TestClock());
        ExecutorService pool = Executors.newFixedThreadPool(8);
        CountDownLatch start = new CountDownLatch(1);
        AtomicInteger allowed = new AtomicInteger();
        for (int t = 0; t < 8; t++) {
            pool.submit(() -> {
                try { start.await(); } catch (InterruptedException e) { return; }
                for (int i = 0; i < 100; i++) if (rl.tryAcquire("shared")) allowed.incrementAndGet();
            });
        }
        start.countDown();
        pool.shutdown();
        assertTrue(pool.awaitTermination(20, TimeUnit.SECONDS));
        assertEquals(50, allowed.get());
    }
}
